/* Nieuwe bonusspellen: Reactiebalancer, Stoffenindeler en Lewisstructuren. */
(()=>{'use strict';
 const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const api=()=>window.ChemieOnline, client=()=>api()?.getClient?.();
 let state={kind:null,session:null,items:[],index:0,correct:0,earned:0,running:false,timer:null,deadline:0,graph:{atoms:[],bonds:[],lonePairs:[]},selected:null,tool:'atom',review:[]};
 function show(html){const host=$('economy-content');if(host){host.innerHTML=html;$('economy-overlay')?.classList.remove('hidden');}}
 function note(t,good=false){const n=$('bonus-game-note');if(n){n.textContent=t;n.className='sprint-feedback '+(good?'good':'bad');}}
 function closeTimer(){if(state.timer)clearInterval(state.timer);state.timer=null;}
 async function finish(){closeTimer();state.running=false;if(state.session&&api()?.isAuthenticated()){try{const {data,error}=await client().rpc('finish_bonus_game',{p_session_id:state.session});if(error)throw error;}catch(e){console.warn(e);}}}
 async function start(kind){
  if(!api()?.isAuthenticated()){show(`<h2 class="economy-title">Log eerst in</h2><p class="economy-lead">Deze bonusspellen bewaren je LabCoins bij je leerlingaccount. Log in via de online chemie-arena.</p>`);return;}
  try{const {data,error}=await client().rpc('start_bonus_game',{p_game_type:kind});if(error)throw error;
   state={...state,kind,session:data.session_id,items:data.items||[],index:0,sequence:0,correct:0,earned:0,running:true,review:[],graph:{atoms:[],bonds:[],lonePairs:[]}};
   if(kind==='classification'||kind==='naming'){state.deadline=Date.now()+60000;renderSprint();state.timer=setInterval(tick,200);}
   else renderQuestion();
  }catch(e){show(`<h2 class="economy-title">Spel nog niet beschikbaar</h2><p class="economy-lead">${esc(e.message||'Controleer de Supabase-migratie en de actieve vragenbank.')}</p>`);}
 }
 function rewardText(){return `${state.correct} juist · ${state.earned} LabCoins`}
 function reactionControls(item){const eq=String(item.prompt||'').replace(/→|⇒|=/g,'->');const parts=eq.split('->');if(parts.length!==2)return `<form id="bonus-answer-form" class="sprint-form"><input class="sprint-input" name="answer" required placeholder="Gebalanceerde vergelijking"><button class="primary" type="submit">Controleer</button></form>`;const sides=parts.map(side=>side.split(/\s+\+\s+/).map(x=>x.trim()).filter(Boolean));if(sides.some(s=>!s.length))return '';const tokens=sides.map(side=>side.map(formula=>{const pure=formula.replace(/^\d+\s*/, '');return `<label class="reaction-term"><input type="number" min="1" max="99" value="1" required data-reaction-coeff><span>${esc(pure)}</span></label>`;}).join('<b> + </b>')).join('<strong> → </strong>');return `<form id="bonus-answer-form" class="reaction-coeff-form"><div class="reaction-equation">${tokens}</div><p class="sprint-score">Vul de coëfficiënten in vóór elke stof.</p><button class="primary" type="submit">Controleer</button></form>`;}
 function renderQuestion(){const item=state.items[state.index];if(!item){finish().then(renderDone);return;}
  const title={reaction:'⚖️ Reactiebalancer',lewis:'⚛️ Lewisstructuren'}[state.kind];
  if(state.kind==='reaction')show(`<p class="economy-eyebrow">BONUSLEVEL · ${state.index+1}/5</p><h2 class="economy-title">${title}</h2><p class="economy-lead">Balanceer de reactievergelijking. Je krijgt één poging; bij een fout zie je meteen de juiste vergelijking.</p><div class="sprint-question"><div class="sprint-element-name">${esc(item.prompt)}</div></div>${reactionControls(item)}<p class="sprint-score">${rewardText()}</p><p id="bonus-game-note" class="sprint-feedback" aria-live="polite"></p>`);
  else renderLewis(item);
 }
 async function submit(answer='',structure=null){if(!state.running)return;const item=state.items[state.index];try{const {data,error}=await client().rpc('submit_bonus_game_answer',{p_session_id:state.session,p_sequence:state.index+1,p_answer:answer,p_structure:structure||{}});if(error)throw error;
   if(data.correct){state.correct++;state.earned+=Number(data.reward)||0;}
   state.review.push({prompt:item.prompt,your:state.kind==='lewis'?'Ingezonden structuur':answer,expected:data.expected_answer,correct:data.correct});
   if(state.kind==='reaction'){
    const feedback=data.correct?`Correct! +${data.reward} LabCoins.`:`Niet correct. De juiste vergelijking is: ${data.expected_answer}.`;
    show(`<p class="economy-eyebrow">REACTIE ${state.index+1}/5</p><h2 class="economy-title">${data.correct?'Goed gedaan!':'Bijna!'}</h2><p class="economy-lead">${esc(feedback)}</p><div class="sprint-results"><div class="sprint-result"><strong>${state.correct}/5</strong><small>Correct</small></div><div class="sprint-result"><strong>+${state.earned}</strong><small>LabCoins</small></div></div><button class="primary full" id="bonus-next">${state.index===4?'Resultaat bekijken':'Volgende reactie'}</button>`);
   }else if(state.kind==='lewis'){
    show(`<p class="economy-eyebrow">STRUCTUUR ${state.index+1}/5</p><h2 class="economy-title">${data.correct?'Structuur goedgekeurd':'Structuur niet goedgekeurd'}</h2><p class="economy-lead">${data.correct?`+${data.reward} LabCoins verdiend.`:'Je inzending komt niet overeen met een goedgekeurd model.'} Feedback verschijnt pas na je inzending.</p><button class="primary full" id="bonus-next">${state.index===4?'Resultaat bekijken':'Volgende structuur'}</button>`);
   }
  }catch(e){note(e.message||'Antwoord kon niet worden nagekeken.');}}
 function renderSprint(){const item=state.items[state.index];if(!item){finish().then(renderDone);return;}const naming=state.kind==='naming';show(`<p class="economy-eyebrow">60 SECONDEN · ${naming?'BENOEMEN':'INDELEN'}</p><h2 class="economy-title">${naming?'🧪 Benoemingssprint':'🧩 Classificatiesprint'}</h2><div class="sprint-hud"><span class="sprint-timer" id="bonus-clock">60</span><span class="sprint-score">${rewardText()}</span></div><div class="sprint-question"><small>${naming?'Geef de naam van de stof':'Tot welke stoffenklasse behoort dit?'}</small><div class="sprint-element-name">${esc(item.prompt)}</div></div><form id="bonus-answer-form" class="sprint-form">${naming?'<input class="sprint-input" name="answer" placeholder="Naam van de stof" autocomplete="off" required>':`<select class="sprint-input" name="answer"><option value="">Kies een klasse…</option><option>oxide</option><option>hydroxide</option><option>zuur</option><option>zout</option></select>`}<button class="primary" type="submit">Antwoord</button></form><p id="bonus-game-note" class="sprint-feedback" aria-live="polite"></p>`);$('bonus-answer-form')?.querySelector('input,select')?.focus();}
 async function sprintAnswer(answer){const item=state.items[state.index];const seq=state.sequence+1;try{const {data,error}=await client().rpc('submit_bonus_game_answer',{p_session_id:state.session,p_sequence:seq,p_answer:answer,p_structure:{}});if(error)throw error;if(data.correct){state.correct++;state.earned+=Number(data.reward)||0;}state.review.push({prompt:item.prompt,your:answer,expected:data.expected_answer,correct:data.correct});state.sequence++;state.index++;if(Date.now()>=state.deadline){await finish();renderDone();}else{if(state.index>=state.items.length){state.index=0;state.items.sort(()=>Math.random()-.5);}renderSprint();}}catch(e){note(e.message||'Antwoord kon niet worden nagekeken.');}}
 function tick(){const left=Math.max(0,Math.ceil((state.deadline-Date.now())/1000));const c=$('bonus-clock');if(c)c.textContent=left;if(left<=0){finish().then(renderDone);}}
 function renderDone(){state.running=false;const rows=state.review.filter(x=>!x.correct).map(x=>`<tr><td>${esc(x.prompt)}</td><td>${esc(x.your)}</td><td>${esc(x.expected)}</td></tr>`).join('');show(`<p class="economy-eyebrow">BONUSLEVEL VOLTOOID</p><h2 class="economy-title">🏆 Goed gewerkt!</h2><div class="sprint-results"><div class="sprint-result"><strong>${state.correct}</strong><small>Correct</small></div><div class="sprint-result"><strong>+${state.earned}</strong><small>LabCoins</small></div><div class="sprint-result"><strong>${state.items.length}</strong><small>Vragen</small></div></div>${rows?`<section class="timed-review"><h3>Te herbekijken</h3><div class="timed-review-scroll"><table class="timed-review-table"><thead><tr><th>Vraag</th><th>Jouw antwoord</th><th>Correct antwoord</th></tr></thead><tbody>${rows}</tbody></table></div></section>`:'<p class="economy-lead">Alle antwoorden waren correct!</p>'}<button class="primary full" id="bonus-retry">Opnieuw spelen</button><button class="secondary full" id="economy-done">Terug naar het labo</button>`);api()?.refreshDashboardSoon?.();}
 function renderLewis(item){const atoms=state.graph.atoms;const svg=`<svg id="lewis-board" viewBox="0 0 600 300" style="width:100%;background:#f4f8fa;border:1px solid #cbd8e2;border-radius:12px;touch-action:manipulation"><rect width="600" height="300" fill="#f4f8fa"/>${state.graph.bonds.map(b=>{const a=atoms.find(x=>x.id===b.a),c=atoms.find(x=>x.id===b.b);if(!a||!c)return'';return `<line x1="${a.x}" y1="${a.y}" x2="${c.x}" y2="${c.y}" stroke="#24475b" stroke-width="${b.order===1?3:2}"/>${b.order>1?`<line x1="${a.x+3}" y1="${a.y+4}" x2="${c.x+3}" y2="${c.y+4}" stroke="#24475b" stroke-width="2"/>`:''}${b.order>2?`<line x1="${a.x-3}" y1="${a.y-4}" x2="${c.x-3}" y2="${c.y-4}" stroke="#24475b" stroke-width="2"/>`:''}`}).join('')}${atoms.map(a=>`<g data-atom="${a.id}"><circle cx="${a.x}" cy="${a.y}" r="23" fill="${a.id===state.selected?'#f7d47a':'#fff'}" stroke="#31576a" stroke-width="2"/><text x="${a.x}" y="${a.y+6}" text-anchor="middle" font-size="18" font-weight="800" fill="#18394f">${esc(a.element)}</text>${(state.graph.lonePairs.find(p=>p.atom===a.id)?.count||0)>0?`<text x="${a.x}" y="${a.y-28}" text-anchor="middle" font-size="16">••</text>`:''}</g>`).join('')}</svg>`;
 show(`<p class="economy-eyebrow">LEWISSTRUCTURE · ${state.index+1}/5</p><h2 class="economy-title">⚛️ Teken de Lewisstructuur</h2><p class="economy-lead">${esc(item.prompt)}. Voeg atomen toe, kies bindingen en plaats vrije elektronenparen. De controle gebeurt pas na je definitieve inzending.</p><div style="display:flex;gap:7px;flex-wrap:wrap;margin:10px 0"><select id="lewis-element"><option> C </option><option>H</option><option>O</option><option>N</option><option>Cl</option><option>F</option><option>S</option><option>P</option></select><button class="secondary" data-lewis-tool="atom">＋ Atoom</button><button class="secondary" data-lewis-tool="bond">Binding</button><select id="lewis-order"><option value="1">Enkel</option><option value="2">Dubbel</option><option value="3">Drievoudig</option></select><button class="secondary" data-lewis-tool="lone">Vrij paar</button><button class="secondary" id="lewis-undo">Ongedaan</button></div>${svg}<p class="sprint-score">Klik op het tekenvlak om atomen te plaatsen; selecteer twee atomen om een binding te maken.</p><button class="primary full" id="lewis-submit">Definitief indienen</button>`);
 }
 function addLewisAtom(x,y,element){const id='a'+(state.graph.atoms.length+1);state.graph.atoms.push({id,x,y,element});state.selected=id;}
 function onBoard(e){const svg=e.target.closest('#lewis-board');if(!svg)return;const rect=svg.getBoundingClientRect(),pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const p=pt.matrixTransform(svg.getScreenCTM().inverse());const hit=e.target.closest('[data-atom]');if(state.tool==='atom'&&!hit){addLewisAtom(Math.round(p.x),Math.round(p.y),$('lewis-element').value.trim());renderLewis(state.items[state.index]);}else if(hit){const id=hit.dataset.atom;if(state.tool==='bond'){if(!state.selected)state.selected=id;else if(state.selected!==id){state.graph.bonds.push({a:state.selected,b:id,order:Number($('lewis-order').value)});state.selected=null;renderLewis(state.items[state.index]);}}else if(state.tool==='lone'){let pair=state.graph.lonePairs.find(x=>x.atom===id);if(pair)pair.count++;else state.graph.lonePairs.push({atom:id,count:1});renderLewis(state.items[state.index]);}else{state.selected=id;renderLewis(state.items[state.index]);}}}
 function canonical(){return {atoms:state.graph.atoms.map(a=>({element:a.element})),bonds:state.graph.bonds.map(b=>({a:state.graph.atoms.findIndex(x=>x.id===b.a),b:state.graph.atoms.findIndex(x=>x.id===b.b),order:b.order})).map(x=>({...x,a:Math.min(x.a,x.b),b:Math.max(x.a,x.b)})).sort((a,b)=>a.a-b.a||a.b-b.b),lonePairs:state.graph.lonePairs.map(p=>({atom:state.graph.atoms.findIndex(x=>x.id===p.atom),count:p.count})).sort((a,b)=>a.atom-b.atom)};}
 $('economy-content')?.addEventListener('submit',e=>{if(e.target.id==='bonus-answer-form'){e.preventDefault();let a=new FormData(e.target).get('answer')||'';if(state.kind==='reaction'&&e.target.querySelector('[data-reaction-coeff]')){const parts=String(state.items[state.index].prompt).replace(/→|⇒|=/g,'->').split('->').map(x=>x.split(/\s+\+\s+/).map(z=>z.trim().replace(/^\d+\s*/,'')));const nums=[...e.target.querySelectorAll('[data-reaction-coeff]')].map(x=>Number(x.value));let n=0;a=parts.map(side=>side.map(formula=>`${nums[n++]===1?'':nums[n-1]+' '}${formula}`).join(' + ')).join(' → ');}if(state.kind==='classification'||state.kind==='naming')sprintAnswer(String(a));else submit(String(a));}});
 $('economy-content')?.addEventListener('click',e=>{if(e.target.closest('#bonus-next')){state.index++;if(state.index>=5){finish().then(renderDone);}else{state.graph={atoms:[],bonds:[],lonePairs:[]};renderQuestion();}}if(e.target.closest('#bonus-retry'))start(state.kind);if(e.target.closest('[data-lewis-tool]')){state.tool=e.target.closest('[data-lewis-tool]').dataset.lewisTool;state.selected=null;}if(e.target.closest('#lewis-submit'))submit('',canonical());if(e.target.closest('#lewis-undo')){state.graph.atoms.pop();state.graph.bonds=state.graph.bonds.filter(b=>state.graph.atoms.some(a=>a.id===b.a)&&state.graph.atoms.some(a=>a.id===b.b));state.graph.lonePairs=state.graph.lonePairs.filter(p=>state.graph.atoms.some(a=>a.id===p.atom));renderLewis(state.items[state.index]);}});
 $('economy-content')?.addEventListener('click',e=>{if(e.target.closest('#lewis-board'))onBoard(e);});
 // Knoppen worden rechtstreeks door game.js gemaakt; geen dynamische duplicaten.
 const bonusLevels={reaction:'medieval',classification:'lavoisier',naming:'lavoisier',lewis:'modern'};
 function chooseStoffenindeler(){show(`<p class="economy-eyebrow">BONUSSPEL · LEVEL 2</p><h2 class="economy-title">🧩 Stoffenindeler</h2><p class="economy-lead">Welke sprint wil je spelen? Elke sprint duurt 60 seconden.</p><button class="primary full" id="bonus-choose-classification">Stoffen classificeren</button><button class="primary full" id="bonus-choose-naming">Stoffen benoemen</button>`);}
 function bindLaunchButtons(){[['reactiebalancer-open',()=>start('reaction')],['stoffenindeler-open',chooseStoffenindeler],['lewisstructuren-open',()=>start('lewis')]].forEach(([id,fn])=>{const el=$(id);if(el&&!el.dataset.bonusBound){el.dataset.bonusBound='1';el.addEventListener('click',()=>{if(!el.disabled)fn();});}});}
 document.addEventListener('click',e=>{if(e.target.closest('#bonus-choose-classification'))start('classification');if(e.target.closest('#bonus-choose-naming'))start('naming');});
 const obs=new MutationObserver(bindLaunchButtons);obs.observe(document.body,{childList:true,subtree:true});bindLaunchButtons();
 // Teacher management tab is added to the existing teacher workspace. CRUD remains protected by RLS.
 function injectTeacherTab(){const nav=document.querySelector('.teacher-management-tabs');if(!nav||nav.querySelector('[data-teacher-tab="bonus"]'))return;const b=document.createElement('button');b.type='button';b.className='teacher-management-tab';b.dataset.teacherTab='bonus';b.textContent='🎯 Bonusspellen';nav.append(b);const shell=document.querySelector('.teacher-management-shell');const section=document.createElement('section');section.id='teacher-panel-bonus';section.className='teacher-tab-panel';section.dataset.teacherPanel='bonus';section.hidden=true;section.innerHTML=`<div class="online-view-heading"><div><h3>🎯 Bonusspellen beheren</h3><p>Drie aparte vragenbanken. Kies een spel om vragen toe te voegen of te bewerken.</p></div></div>
<div class="bonus-teacher-tabs" role="tablist"><button type="button" data-bonus-bank="reaction" class="active">⚖️ Reactiebalancer</button><button type="button" data-bonus-bank="substances">🧩 Stoffenindeler</button><button type="button" data-bonus-bank="lewis">⚛️ Lewisstructuren</button></div>
<form id="bonus-teacher-form" class="teacher-question-form"><input type="hidden" id="bti-id"><label id="bti-type-label">Soort vraag<select id="bti-type"><option value="reaction">Reactiebalancer</option><option value="classification">Classificatiesprint</option><option value="naming">Benoemingssprint</option><option value="lewis">Lewisstructuren</option></select></label><label id="bti-difficulty-label">Moeilijkheid<select id="bti-difficulty"><option>basis</option><option>gemiddeld</option><option>moeilijk</option></select></label><label class="span-all" id="bti-prompt-label">Vraag / formule<textarea id="bti-prompt" required maxlength="1000"></textarea></label><label class="span-all" id="bti-answer-label">Correct gebalanceerde vergelijking<input id="bti-answer" placeholder="2 H₂ + O₂ → 2 H₂O"></label><label id="bti-category-label">Stoffenklasse<select id="bti-category"><option value="">Kies klasse…</option><option value="oxide">oxide</option><option value="hydroxide">hydroxide</option><option value="zuur">zuur</option><option value="zout">zout</option></select></label><label class="span-all" id="bti-accepted-label">Aanvaarde namen (één per regel, maximaal twee)<textarea id="bti-accepted" rows="3"></textarea></label>
<div class="span-all" id="bti-lewis-editor"><h4>Lewisstructuur tekenen</h4><p>Voeg atomen toe op het tekenvlak. Kies ‘Binding’ en klik twee atomen aan; kies ‘Vrij paar’ en klik een atoom aan. De plaats en tekenvolgorde maken niet uit bij het nakijken.</p><div class="bonus-draw-toolbar"><label>Element<select id="teacher-lewis-element"><option>C</option><option>H</option><option>O</option><option>N</option><option>Cl</option><option>F</option><option>S</option><option>P</option><option>Br</option><option>I</option></select></label><button type="button" data-teacher-lewis-tool="atom">＋ Atoom</button><button type="button" data-teacher-lewis-tool="bond">Binding</button><label>Binding<select id="teacher-lewis-order"><option value="1">Enkel</option><option value="2">Dubbel</option><option value="3">Drievoudig</option></select></label><button type="button" data-teacher-lewis-tool="lone">Vrij paar</button><button type="button" id="teacher-lewis-undo">Ongedaan</button><button type="button" id="teacher-lewis-clear">Wissen</button></div><svg id="teacher-lewis-board" viewBox="0 0 600 300" role="img" aria-label="Lewisstructuur tekenvenster"></svg><p id="teacher-lewis-count"></p><details><summary>Geavanceerd: structuurgegevens (JSON)</summary><textarea id="bti-model" rows="5" placeholder="Wordt automatisch uit de tekening opgebouwd"></textarea></details></div>
<label class="span-all">Uitleg / feedback<textarea id="bti-explanation" rows="2"></textarea></label><label><input id="bti-active" type="checkbox" checked> Actief voor leerlingen</label><div class="span-all"><button class="online-primary" type="submit">Vraag opslaan</button><button class="online-secondary" type="button" id="bti-reset">Nieuwe vraag</button></div><p id="bti-status" class="teacher-question-status span-all"></p></form><div id="bonus-teacher-list" class="teacher-question-grid"></div>`;shell.append(section);selectBank('reaction');nav.addEventListener('click',e=>{const t=e.target.closest('[data-teacher-tab]');if(!t)return;nav.querySelectorAll('[data-teacher-tab]').forEach(x=>{const on=x===t;x.classList.toggle('active',on);x.setAttribute('aria-selected',String(on));});shell.querySelectorAll('[data-teacher-panel]').forEach(p=>p.hidden=p.dataset.teacherPanel!==t.dataset.teacherTab);if(t.dataset.teacherTab==='bonus')loadTeacherItems();});
 }
 async function loadTeacherItems(){const c=client();if(!c)return;const box=$('bonus-teacher-list');if(!box)return;const {data,error}=await c.from('bonus_game_items').select('*').in('game_type',activeBank==='substances'?['classification','naming']:[activeBank]).order('created_at',{ascending:false});if(error){box.textContent='Voer eerst de meegeleverde Supabase-migratie uit.';return;}box.innerHTML=(data||[]).map(i=>`<article class="teacher-question-card"><strong>${esc(i.prompt)}</strong><p>${esc(i.game_type)} · ${esc(i.difficulty)} · ${i.is_active?'Actief':'Inactief'}</p><small>${esc(i.answer||i.category||'Lewismodel')}</small><div><button type="button" class="online-small-btn" data-bti-edit="${i.id}">Bewerken</button> <button type="button" class="online-small-btn" data-bti-toggle="${i.id}">${i.is_active?'Deactiveren':'Activeren'}</button> <button type="button" class="teacher-delete-btn" data-bti-delete="${i.id}">Verwijderen</button></div></article>`).join('')||'<p class="online-help">Nog geen bonusvragen. Voeg hierboven de eerste vraag toe.</p>';box._rows=data||[];}
 let activeBank='reaction';
 let teacherGraph={atoms:[],bonds:[],lonePairs:[]},teacherTool='atom',teacherSelected=null,teacherHistory=[];
 const bankType=type=>type==='reaction'?'reaction':type==='lewis'?'lewis':'substances';
 function graphSnapshot(){teacherHistory.push(JSON.stringify(teacherGraph));if(teacherHistory.length>50)teacherHistory.shift();}
 function teacherCanonical(){const atoms=teacherGraph.atoms;return {atoms:atoms.map(a=>({element:a.element})),bonds:teacherGraph.bonds.map(b=>({a:atoms.findIndex(a=>a.id===b.a),b:atoms.findIndex(a=>a.id===b.b),order:b.order})),lonePairs:teacherGraph.lonePairs.map(x=>({atom:atoms.findIndex(a=>a.id===x.atom),count:x.count}))};}
 function loadTeacherGraph(model){teacherGraph={atoms:(model.atoms||[]).map((a,i)=>({id:'t'+i,element:a.element,x:90+(i%5)*95,y:80+Math.floor(i/5)*95})),bonds:[],lonePairs:[]};teacherGraph.bonds=(model.bonds||[]).map(b=>({a:teacherGraph.atoms[b.a]?.id,b:teacherGraph.atoms[b.b]?.id,order:b.order||1})).filter(b=>b.a&&b.b);teacherGraph.lonePairs=(model.lonePairs||[]).map(x=>({atom:teacherGraph.atoms[x.atom]?.id,count:x.count})).filter(x=>x.atom);teacherHistory=[];teacherSelected=null;drawTeacherGraph();}
 function drawTeacherGraph(){const svg=$('teacher-lewis-board');if(!svg)return;const a=teacherGraph.atoms;svg.innerHTML='<rect width="600" height="300" fill="#f5fafb"/>'+teacherGraph.bonds.map(b=>{const u=a.find(x=>x.id===b.a),v=a.find(x=>x.id===b.b);if(!u||!v)return '';const dx=v.x-u.x,dy=v.y-u.y,len=Math.hypot(dx,dy)||1,px=-dy/len*5,py=dx/len*5;return Array.from({length:b.order},(_,i)=>{const off=i-(b.order-1)/2;return `<line x1="${u.x+px*off}" y1="${u.y+py*off}" x2="${v.x+px*off}" y2="${v.y+py*off}" stroke="#24536b" stroke-width="3"/>`;}).join('');}).join('')+a.map(x=>{const pairs=teacherGraph.lonePairs.find(p=>p.atom===x.id)?.count||0;return `<g data-teacher-atom="${x.id}"><circle cx="${x.x}" cy="${x.y}" r="24" fill="${teacherSelected===x.id?'#ffdf8d':'white'}" stroke="#31576a" stroke-width="2"/><text x="${x.x}" y="${x.y+6}" text-anchor="middle" font-size="18" font-weight="800">${esc(x.element)}</text><text x="${x.x}" y="${x.y-29}" text-anchor="middle" font-size="16">${'•• '.repeat(pairs)}</text></g>`;}).join('');$('teacher-lewis-count').textContent=`${a.length}/14 atomen · ${teacherGraph.bonds.length} bindingen`;}
 function selectBank(bank){activeBank=bank;document.querySelectorAll('[data-bonus-bank]').forEach(b=>b.classList.toggle('active',b.dataset.bonusBank===bank));const type=$('bti-type');if(bank==='reaction')type.value='reaction';else if(bank==='lewis')type.value='lewis';else if(!['classification','naming'].includes(type.value))type.value='classification';const lewis=bank==='lewis',sub=bank==='substances';$('bti-type-label').hidden=!sub;$('bti-difficulty-label').hidden=sub;$('bti-answer-label').hidden=lewis||sub;$('bti-category-label').hidden=!sub;$('bti-accepted-label').hidden=!sub;$('bti-lewis-editor').hidden=!lewis;$('bti-prompt-label').firstChild.textContent=lewis?'Stof / opdracht':sub?'Formule van de stof':'Reactievergelijking (zonder of met coëfficiënten)';if(bank==='reaction')$('bti-answer-label').firstChild.textContent='Correct gebalanceerde vergelijking';if(sub)$('bti-accepted-label').firstChild.textContent='Naam/namen (één per regel, maximaal twee)';loadTeacherItems();if(lewis)drawTeacherGraph();}
 function resetTeacher(){const form=$('bonus-teacher-form');form.reset();$('bti-id').value='';teacherGraph={atoms:[],bonds:[],lonePairs:[]};teacherHistory=[];teacherSelected=null;selectBank(activeBank);}
 document.addEventListener('click',e=>{const tab=e.target.closest('[data-bonus-bank]');if(tab){resetTeacher();selectBank(tab.dataset.bonusBank);return;}if(e.target.closest('#bti-reset')){resetTeacher();return;}const tool=e.target.closest('[data-teacher-lewis-tool]');if(tool){teacherTool=tool.dataset.teacherLewisTool;teacherSelected=null;drawTeacherGraph();return;}if(e.target.closest('#teacher-lewis-clear')){graphSnapshot();teacherGraph={atoms:[],bonds:[],lonePairs:[]};teacherSelected=null;drawTeacherGraph();return;}if(e.target.closest('#teacher-lewis-undo')){if(teacherHistory.length){teacherGraph=JSON.parse(teacherHistory.pop());teacherSelected=null;drawTeacherGraph();}return;}
 const svg=e.target.closest('#teacher-lewis-board');if(!svg||activeBank!=='lewis')return;const hit=e.target.closest('[data-teacher-atom]');if(hit){const id=hit.dataset.teacherAtom;if(teacherTool==='bond'){if(!teacherSelected){teacherSelected=id;}else if(teacherSelected!==id){graphSnapshot();const old=teacherGraph.bonds.find(b=>(b.a===id&&b.b===teacherSelected)||(b.b===id&&b.a===teacherSelected));if(old)old.order=Number($('teacher-lewis-order').value);else teacherGraph.bonds.push({a:teacherSelected,b:id,order:Number($('teacher-lewis-order').value)});teacherSelected=null;}}else if(teacherTool==='lone'){graphSnapshot();const pair=teacherGraph.lonePairs.find(p=>p.atom===id);if(pair)pair.count=Math.min(4,pair.count+1);else teacherGraph.lonePairs.push({atom:id,count:1});}else teacherSelected=id;}else if(teacherTool==='atom'&&teacherGraph.atoms.length<14){const pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const pos=pt.matrixTransform(svg.getScreenCTM().inverse());graphSnapshot();teacherGraph.atoms.push({id:'t'+Date.now()+Math.random(),x:Math.max(30,Math.min(570,Math.round(pos.x))),y:Math.max(35,Math.min(270,Math.round(pos.y))),element:$('teacher-lewis-element').value});}drawTeacherGraph();});
 document.addEventListener('submit',async e=>{if(e.target.id!=='bonus-teacher-form')return;e.preventDefault();const c=client(),id=$('bti-id').value,type=activeBank==='substances'?'classification':activeBank;try{let models=[];if(activeBank==='lewis'){const json=$('bti-model').value.trim();if(json){const parsed=JSON.parse(json);models=Array.isArray(parsed)?parsed:[parsed];}else models=[teacherCanonical()];if(!models.length||models.some(m=>!m.atoms?.length||m.atoms.length>14))throw new Error('Teken 1 tot 14 atomen in de Lewisstructuur.');}const names=$('bti-accepted').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(activeBank==='substances'&&(!$('bti-category').value||!names.length||names.length>2))throw new Error('Geef een stoffenklasse en één of twee namen op.');if(activeBank==='reaction'&&!$('bti-answer').value.trim())throw new Error('Geef de correcte gebalanceerde vergelijking op.');const common={difficulty:$('bti-difficulty').value,prompt:$('bti-prompt').value.trim(),answer:activeBank==='reaction'?$('bti-answer').value.trim():activeBank==='substances'?names[0]:'',category:activeBank==='substances'?$('bti-category').value:'',accepted_answers:activeBank==='substances'?names:[],accepted_models:models,model:models[0]||{},explanation:$('bti-explanation').value.trim(),is_active:$('bti-active').checked,updated_at:new Date().toISOString()};
 const rows=activeBank==='substances'?[{...common,game_type:'classification'},{...common,game_type:'naming'}]:[{...common,game_type:type}];if(id){const {error}=await c.from('bonus_game_items').update(rows[0]).eq('id',id);if(error)throw error;}else for(const row of rows){const {error}=await c.from('bonus_game_items').insert(row);if(error)throw error;}$('bti-status').textContent='Opgeslagen.';resetTeacher();}catch(err){$('bti-status').textContent=err.message||'Opslaan mislukt.';}});
 document.addEventListener('click',async e=>{const edit=e.target.closest('[data-bti-edit]'),toggle=e.target.closest('[data-bti-toggle]'),del=e.target.closest('[data-bti-delete]');if(!edit&&!toggle&&!del)return;const c=client(),box=$('bonus-teacher-list'),target=edit||toggle||del,key=edit?'btiEdit':toggle?'btiToggle':'btiDelete',row=box?._rows?.find(x=>x.id===target.dataset[key]);try{if(edit&&row){selectBank(bankType(row.game_type));$('bti-id').value=row.id;$('bti-type').value=row.game_type;$('bti-difficulty').value=row.difficulty;$('bti-prompt').value=row.prompt;$('bti-answer').value=row.answer||'';$('bti-category').value=row.category||'';$('bti-accepted').value=(row.accepted_answers||[]).join('\n');$('bti-model').value='';$('bti-explanation').value=row.explanation||'';$('bti-active').checked=row.is_active;if(row.game_type==='lewis')loadTeacherGraph(row.accepted_models?.[0]||row.model||{});}else if(toggle){const r=box._rows.find(x=>x.id===toggle.dataset.btiToggle);const {error}=await c.from('bonus_game_items').update({is_active:!r.is_active}).eq('id',r.id);if(error)throw error;await loadTeacherItems();}else if(del&&confirm('Deze bonusvraag definitief verwijderen?')){const {error}=await c.from('bonus_game_items').delete().eq('id',del.dataset.btiDelete);if(error)throw error;await loadTeacherItems();}}catch(err){alert(err.message||'Actie mislukt.');}});
 const teacherObs=new MutationObserver(injectTeacherTab);teacherObs.observe(document.body,{childList:true,subtree:true});injectTeacherTab();
 $('economy-overlay')?.addEventListener('click',e=>{if(e.target.closest('#economy-close')&&state.running)finish();});
 window.BonusGames={start,finish,isRunning:()=>state.running};
})();
